-- ============================================
-- LUMA — Thème 12 : MOYEN 1/3 x4 — Une visite libre avec un audioguide interactif
-- ============================================


update scenarios set content = '{"characters": {"audioguide": "l''audioguide"}, "start_node": "n1", "nodes": {"n1": {"speaker": "audioguide", "text": "Welcome to the museum''s interactive audio guide. Which section interests you most today?", "text_fr": "Bienvenue au guide audio interactif du musée. Quelle section vous intéresse le plus aujourd''hui ?", "choices": [{"text": "I''d love to explore the ancient civilizations wing.", "text_fr": "J''aimerais explorer l''aile des civilisations anciennes.", "next": "n2"}, {"text": "The modern art section sounds appealing to me.", "text_fr": "La section d''art moderne me semble intéressante.", "next": "n2b"}]}, "n2": {"speaker": "audioguide", "text": "Excellent choice! You''ll find artifacts spanning three thousand years of history here.", "text_fr": "Excellent choix ! Vous trouverez ici des artefacts couvrant trois mille ans d''histoire.", "choices": [{"text": "Tell me about the most significant piece in this section.", "text_fr": "Parlez-moi de la pièce la plus significative de cette section.", "next": "n3"}]}, "n2b": {"speaker": "audioguide", "text": "Wonderful! This section challenges traditional artistic boundaries in fascinating ways.", "text_fr": "Merveilleux ! Cette section défie les frontières artistiques traditionnelles de façon fascinante.", "choices": [{"text": "What makes this collection particularly unique?", "text_fr": "Qu''est-ce qui rend cette collection particulièrement unique ?", "next": "n3"}]}, "n3": {"speaker": "audioguide", "text": "The centerpiece is a ceremonial mask, believed to hold spiritual significance for its creators.", "text_fr": "La pièce maîtresse est un masque cérémoniel, censé avoir une importance spirituelle pour ses créateurs.", "choices": [{"text": "That''s fascinating, can you tell me more about its origins?", "text_fr": "C''est fascinant, vous pouvez m''en dire plus sur ses origines ?", "next": "n4"}, {"text": "I''d like to move on to see other artifacts nearby.", "text_fr": "J''aimerais continuer pour voir d''autres artefacts à proximité.", "next": "n4b"}]}, "n4": {"speaker": "audioguide", "text": "It was discovered in a burial site, suggesting it played a role in important ceremonies.", "text_fr": "Il a été découvert dans un site funéraire, suggérant qu''il jouait un rôle dans des cérémonies importantes.", "choices": [{"text": "That gives it such a powerful historical weight.", "text_fr": "Ça lui donne un poids historique tellement puissant.", "next": "n5"}]}, "n4b": {"speaker": "audioguide", "text": "Of course! Just ahead, you''ll find pottery from the same era, equally fascinating.", "text_fr": "Bien sûr ! Juste devant, vous trouverez de la poterie de la même époque, tout aussi fascinante.", "choices": [{"text": "Let''s explore that next then.", "text_fr": "Explorons ça ensuite alors.", "next": "n5"}]}, "n5": {"speaker": "audioguide", "text": "Would you like to continue deeper into this wing, or explore a different section entirely?", "text_fr": "Vous voulez continuer plus profondément dans cette aile, ou explorer une section entièrement différente ?", "choices": [{"text": "Let''s continue deeper — I''m really enjoying this.", "text_fr": "Continuons plus profondément — j''apprécie vraiment ça.", "next": "n6"}, {"text": "Actually, let''s switch to the natural history section now.", "text_fr": "En fait, passons à la section d''histoire naturelle maintenant.", "next": "n6b"}]}, "n6": {"speaker": "audioguide", "text": "Wonderful choice, deeper in you''ll find the museum''s most prized collection.", "text_fr": "Merveilleux choix, plus profondément vous trouverez la collection la plus précieuse du musée.", "choices": [{"text": "I can''t wait to see what that includes.", "text_fr": "J''ai hâte de voir ce que ça inclut.", "next": "n7"}]}, "n6b": {"speaker": "audioguide", "text": "Great choice for variety! The natural history section offers a completely different experience.", "text_fr": "Excellent choix pour varier ! La section d''histoire naturelle offre une expérience complètement différente.", "choices": [{"text": "I love museums that offer this kind of range.", "text_fr": "J''adore les musées qui offrent ce genre de diversité.", "next": "n7"}]}, "n7": {"speaker": "audioguide", "text": "That''s the beauty of self-guided exploration — you shape your own journey through history.", "text_fr": "C''est la beauté de l''exploration autonome — vous façonnez votre propre parcours à travers l''histoire.", "choices": [{"text": "This has honestly been such an enriching experience so far.", "text_fr": "Ça a honnêtement été une expérience si enrichissante jusqu''ici.", "next": "end_explored"}]}, "end_explored": {"speaker": "audioguide", "text": "I''m delighted to have guided part of your journey. Enjoy the rest of your visit!", "text_fr": "Je suis ravi d''avoir guidé une partie de votre parcours. Profitez du reste de votre visite !", "end": true, "ending_label": "Visite autonome riche et personnalisée 🎧🏛️"}}}'::jsonb, is_playable = true
where title = 'Une visite libre avec un audioguide interactif'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
